package com.simpletoob.app;

import android.app.AlertDialog;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.session.*;
import androidx.media3.session.MediaController;
import com.google.common.util.concurrent.ListenableFuture;
import java.util.*;

/** Native playlist player. The service keeps playing when this screen closes. */
public final class AudioActivity extends BaseActivity {
    private MediaController controller;private ListenableFuture<MediaController> connection;
    private TextView title,artist,status,time;private ImageView art;private ImageButton play;private Button shuffle,repeat;
    private SeekBar seek;private ListView queue;private BaseAdapter rows;private boolean dragging,started,handledIntent;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final Player.Listener listener=new Player.Listener(){@Override public void onEvents(Player player,Player.Events events){refresh();}@Override public void onPlayerError(PlaybackException error){refresh();}};
    private final Runnable tick=new Runnable(){public void run(){refreshPosition();if(started)handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);handledIntent=state!=null&&state.getBoolean("handled");LinearLayout root=ui.column();ui.root(root);LinearLayout bar=ui.toolbar("Audio",this::finish);bar.addView(ui.icon("library","Choose a playlist",this::choosePlaylist));bar.addView(ui.icon("settings","Audio options",this::options));root.addView(bar);
        ScrollView scroll=new ScrollView(this);LinearLayout content=ui.column();ui.padded(content);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(ui.rounded(ui.surface,ui.square?0:16));art.setClipToOutline(true);content.addView(art,new LinearLayout.LayoutParams(-1,ui.dp(200)));art.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int size=Math.min(ui.dp(280),r-l);if(size>0&&v.getLayoutParams().height!=size){v.getLayoutParams().height=size;v.requestLayout();}});ui.space(content,16);
        title=ui.heading("Your music. Your queue.",22);content.addView(title);artist=ui.note("Choose Saved videos or any local/imported playlist. No account required.");content.addView(artist);status=ui.note("");content.addView(status);ui.space(content,10);
        seek=new SeekBar(this);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(ui.accent));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(ui.accent));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){dragging=true;}public void onStopTrackingTouch(SeekBar b){dragging=false;if(controller!=null)controller.seekTo(b.getProgress());}public void onProgressChanged(SeekBar b,int value,boolean user){}});content.addView(seek);time=ui.note("0:00 / 0:00");content.addView(time);
        LinearLayout controls=ui.row();controls.setGravity(Gravity.CENTER);controls.addView(ui.icon("previous","Previous track",()->{if(controller!=null)controller.seekToPrevious();}));play=ui.icon("play","Play or pause",()->{if(controller==null)return;if(controller.isPlaying())controller.pause();else{if(controller.getPlayerError()!=null){MediaItem item=controller.getCurrentMediaItem();if(item!=null)app.youtube.invalidateMedia(item.mediaId);}controller.prepare();controller.play();}});controls.addView(play,new LinearLayout.LayoutParams(ui.dp(72),ui.dp(64)));controls.addView(ui.icon("next","Next track",()->{if(controller!=null)controller.seekToNextMediaItem();}));content.addView(controls);
        LinearLayout modes=ui.row();shuffle=ui.quiet("Shuffle off",()->{if(controller!=null)controller.setShuffleModeEnabled(!controller.getShuffleModeEnabled());});repeat=ui.quiet("Repeat off",()->{if(controller!=null)controller.setRepeatMode((controller.getRepeatMode()+1)%3);});modes.addView(shuffle,new LinearLayout.LayoutParams(0,-2,1));modes.addView(repeat,new LinearLayout.LayoutParams(0,-2,1));content.addView(modes);content.addView(ui.chip("library","Choose playlist",this::choosePlaylist));
        LinearLayout queueHead=ui.row();queueHead.setPadding(ui.dp(16),ui.dp(8),ui.dp(16),0);queueHead.addView(ui.heading("Queue",16),new LinearLayout.LayoutParams(0,-2,1));queueHead.addView(ui.icon("more","Queue and sleep timer options",this::options));root.addView(queueHead);
        queue=new ListView(this);queue.setDivider(null);rows=new BaseAdapter(){public int getCount(){return controller==null?0:controller.getMediaItemCount();}public Object getItem(int p){return controller.getMediaItemAt(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){TextView text=old instanceof TextView?(TextView)old:ui.text("",14,ui.text);MediaItem item=controller.getMediaItemAt(p);text.setPadding(ui.dp(16),ui.dp(12),ui.dp(16),ui.dp(12));text.setMaxLines(2);text.setEllipsize(android.text.TextUtils.TruncateAt.END);text.setText((p==controller.getCurrentMediaItemIndex()?"▶  ":(p+1)+".  ")+item.mediaMetadata.title);text.setTextColor(p==controller.getCurrentMediaItemIndex()?ui.accent:ui.text);return text;}};queue.setAdapter(rows);queue.setOnItemClickListener((p,v,i,id)->{if(controller!=null){controller.seekTo(i,0);controller.prepare();controller.play();}});root.addView(queue,new LinearLayout.LayoutParams(-1,ui.dp(160)));
    }
    @Override protected void onStart(){super.onStart();started=true;connection=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,AudioService.class))).buildAsync();final ListenableFuture<MediaController> pending=connection;connection.addListener(()->{try{if(!started||connection!=pending)return;controller=pending.get();controller.addListener(listener);refresh();if(!handledIntent){handledIntent=true;String local=getIntent().getStringExtra("local_playlist"),raw=getIntent().getStringExtra("video");if(local!=null)load(local);else if(raw!=null)startQueue(Collections.singletonList(Video.fromJson(new org.json.JSONObject(raw))));}}catch(Exception e){error("Couldn't connect to the audio player. Please reopen Audio.");}},this::runOnUiThread);handler.post(tick);}
    @Override protected void onStop(){started=false;handler.removeCallbacks(tick);if(controller!=null)controller.removeListener(listener);controller=null;if(connection!=null)MediaController.releaseFuture(connection);connection=null;super.onStop();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("handled",handledIntent);}
    private void refresh(){if(controller==null)return;MediaMetadata m=controller.getMediaMetadata();if(controller.getMediaItemCount()>0){title.setText(m.title==null?"Audio":m.title);artist.setText(m.artist==null?"":m.artist);String url=m.artworkUri==null?"":m.artworkUri.toString();if(!url.equals(art.getTag()))app.thumbnails.load(url,art);}play.setImageDrawable(new AppIcons(controller.isPlaying()?"pause":"play",ui.accent));shuffle.setText(controller.getShuffleModeEnabled()?"Shuffle on":"Shuffle off");repeat.setText(controller.getRepeatMode()==Player.REPEAT_MODE_ONE?"Repeat track":controller.getRepeatMode()==Player.REPEAT_MODE_ALL?"Repeat queue":"Repeat off");PlaybackException error=controller.getPlayerError();status.setText(error!=null?"Couldn't play this track ("+error.getErrorCodeName()+"). Tap Play to retry or skip it.":controller.getPlaybackState()==Player.STATE_BUFFERING?"Loading audio…":controller.getMediaItemCount()==0?"":controller.isPlaying()?"Audio only · continues with the screen off":"Paused");rows.notifyDataSetChanged();refreshPosition();}
    private void refreshPosition(){if(controller==null||dragging)return;if(AudioService.queueLoading)status.setText("Loading playlist…");else if(!AudioService.queueError.isEmpty())status.setText(AudioService.queueError);long duration=controller.getDuration(),position=controller.getCurrentPosition();seek.setEnabled(duration>0);seek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(0,duration)));seek.setProgress((int)Math.min(Integer.MAX_VALUE,position));time.setText(clock(position)+" / "+clock(Math.max(0,duration))+(AudioService.sleepUntil>0?" · sleep "+Math.max(1,(AudioService.sleepUntil-SystemClock.elapsedRealtime()+59999)/60000)+"m":""));}
    private static String clock(long ms){long s=ms/1000;return String.format(Locale.ROOT,"%d:%02d",s/60,s%60);}
    private void choosePlaylist(){if(controller==null){toast("Audio player is connecting…");return;}LibraryStore library=app.library;work(app.disk,library::playlists,lists->{List<String> names=new ArrayList<>();names.add("Saved videos");for(LibraryStore.LocalPlaylist p:lists)names.add(p.name+" · "+p.size+" tracks");new AlertDialog.Builder(this).setTitle("Play audio from").setItems(names.toArray(new String[0]),(d,i)->load(i==0?"":lists.get(i-1).id)).setNegativeButton("Cancel",null).show();},this::error);}
    private void load(String id){if(controller==null)return;startService(new Intent(this,AudioService.class).setAction("playlist").putExtra("id",id).putExtra("profile",app.prefs.text("profile","default")));status.setText("Loading playlist…");}
    private void startQueue(List<Video> videos){if(controller==null||videos.isEmpty())return;startService(new Intent(this,AudioService.class).setAction("video").putExtra("video",videos.get(0).json().toString()).putExtra("profile",app.prefs.text("profile","default")));status.setText("Loading audio…");}
    private void options(){new AlertDialog.Builder(this).setTitle("Audio options").setItems(new String[]{"Sleep timer","Clear queue and stop","Audio/network settings"},(d,i)->{if(i==0)new AlertDialog.Builder(this).setTitle("Stop audio after").setItems(new String[]{"Off","15 minutes","30 minutes","60 minutes","120 minutes"},(dialog,n)->{int minutes=new int[]{0,15,30,60,120}[n];if(minutes>0&&(controller==null||controller.getMediaItemCount()==0)){toast("Start audio before setting a sleep timer.");return;}startService(new Intent(this,AudioService.class).setAction("sleep").putExtra("minutes",minutes));toast(minutes==0?"Sleep timer off":"Sleep timer set");}).show();else if(i==1&&controller!=null){startService(new Intent(this,AudioService.class).setAction("clear"));art.setTag(null);art.setImageDrawable(null);title.setText("Your music. Your queue.");artist.setText("Choose a playlist to start listening.");}else if(i==2)startActivity(new Intent(this,MainActivity.class).putExtra("open_screen","Settings"));}).show();}
}
